style.css:
@-moz-document domain("google.com") {
:root {
    color-scheme: dark !important;
    --steam-bg: #071426;
    --steam-panel: #10243b;
    --steam-blue: #1a9fff;
    --steam-glow: #00baff;
    --steam-text: #e6f1ff;
  }

  html, body {
    background: var(--steam-bg) !important;
    color: var(--steam-text) !important;
  }

  a {
    color: #66c0f4 !important;
  }

  input, textarea {
    background: #0b1b2e !important;
    color: white !important;
    border: 1px solid var(--steam-blue) !important;
    border-radius: 24px !important;
    box-shadow: 0 0 8px #008cff44 !important;
  }

  button,
  input[type="button"],
  input[type="submit"] {
    background: linear-gradient(135deg, #123456, #0879c9) !important;
    color: white !important;
    border: 1px solid var(--steam-blue) !important;
    border-radius: 20px !important;
    transition: 0.2s ease !important;
  }

  button:hover,
  input[type="button"]:hover,
  input[type="submit"]:hover {
    box-shadow: 0 0 14px var(--steam-glow) !important;
    filter: brightness(1.2) !important;
  }

  header, footer {
    background: #08182a !important;
  }

  ::selection {
    background: #087dce !important;
    color: white !important;
  }

  * {
    scrollbar-color: #168de0 #071426 !important;
  }
}
